 private static IEnumerable<Metric> AvailableMetrics(Device device,Metric? primary)=>device.Metrics.Where(m=>m.Unit!="IP"&&m.TextValue==null).OrderBy(m=>m.Id==primary?.Id?0:1);
 private static Color Blend(Color a,Color b,double ratio)=>Color.FromRgb((byte)(a.R+(b.R-a.R)*ratio),(byte)(a.G+(b.G-a.G)*ratio),(byte)(a.B+(b.B-a.B)*ratio));
 private static Brush Tint(string color,double alpha,double opacity){var b=Ui.Brush(color);b.Opacity=alpha*opacity;return b;}
 private HistoryAreaGraph Plot(Metric? metric,string accent,string track,Preferences p){var chart=new HistoryAreaGraph(accent,track,DesignCatalog.GraphSize(p)){ToolTip=(metric==null?"Unavailable":Ui.SidebarFullLabel(metric.Label)+" · "+metric.Unit)+" · last 60 seconds · real samples only"};if(metric!=null)plots.Add((metric,chart));return chart;}
 public void Update(Device device,Preferences p)
 {
  foreach(var pair in values){var metric=device.Metrics.FirstOrDefault(m=>m.Id==pair.Key);pair.Value.Text=metric?.Display(p.Fahrenheit)??"—";pair.Value.ToolTip=metric==null?"Unavailable":Ui.SidebarFullLabel(metric.Label)+" · "+pair.Value.Text+(metric.Source==null?"":"\n"+metric.Source);}
  var primary=device.Metrics.FirstOrDefault(m=>m.Id==primaryId);string display=primary?.Display(p.Fahrenheit)??"—";int split=display.LastIndexOf(' ');number.Text=split<0?display:display[..split];unit.Text=split<0?primary?.Unit??"":display[(split+1)..];number.ToolTip=primary==null?"Unavailable":Ui.SidebarFullLabel(primary.Label)+" · "+display;
  foreach(var pair in plots){pair.Plot.SetSamples(history.Read(deviceId,pair.Metric.Id),history.LatestTime,pair.Metric.Unit=="%"?100:pair.Metric.Unit=="°C"?Math.Max(100,pair.Metric.Maximum):0,TimeSpan.FromMilliseconds(Math.Max(2500,p.Interval*2.5)));}
  foreach(var pair in meters){var metric=device.Metrics.FirstOrDefault(m=>m.Id==pair.Id);pair.Meter.Available=metric?.Value is double v&&double.IsFinite(v);pair.Meter.Ratio=metric?.Value is double raw&&double.IsFinite(raw)?Math.Clamp(raw/Math.Max(1,metric.Unit is "%" or "°C"?100:double.IsFinite(metric.Maximum)?metric.Maximum:100),0,1):0;pair.Meter.ToolTip=metric==null?"Unavailable":Ui.SidebarFullLabel(metric.Label)+" · "+metric.Display(p.Fahrenheit);pair.Meter.InvalidateVisual();}
  BorderBrush=device.Metrics.Any(m=>m.Value.HasValue&&((m.Unit=="°C"&&m.Value>=p.TempLimit)||(m.Label=="Auslastung"&&m.Value>=p.LoadLimit)))?Ui.Brush("#F47777"):edge;
