 // Whole-graphic scaling stays independent of the individual text-size settings.
 private sealed class AdaptiveGraphic:Decorator
 {
  private readonly Size natural;private readonly double requested;private double factor=1;
  public AdaptiveGraphic(UIElement child,Size natural,double requested){Child=child;this.natural=natural;this.requested=requested;ClipToBounds=true;}
  protected override Size MeasureOverride(Size available){factor=Math.Min(requested,double.IsFinite(available.Width)?Math.Max(.001,available.Width/natural.Width):requested);Child.Measure(natural);return new Size(natural.Width*factor,natural.Height*factor);}
  protected override Size ArrangeOverride(Size final){double scale=Math.Min(factor,Math.Max(.001,final.Width/natural.Width));Child.Arrange(new Rect(new Point(),natural));Child.RenderTransform=new ScaleTransform(scale,scale);return final;}
 }
 private sealed class LinearSensorMeter:FrameworkElement
 {
  public double Ratio;public bool Available;private readonly Brush ink,track;private readonly double thickness;private readonly bool vertical,glass;
  public LinearSensorMeter(string accent,string track,double thickness,bool vertical,bool glass){ink=Ui.Brush(accent);this.track=Ui.Brush(track);this.thickness=thickness;this.vertical=vertical;this.glass=glass;IsHitTestVisible=false;}
  protected override void OnRender(DrawingContext dc){double w=ActualWidth,h=ActualHeight;if(w<3||h<3)return;if(glass){dc.DrawRoundedRectangle(null,new Pen(track,1),new Rect(2,2,Math.Max(1,w-4),Math.Max(1,h-4)),17,17);dc.DrawLine(new Pen(ink,2*thickness),new Point(3,19),new Point(3,Math.Max(19,h-19)));if(Available){var color=((SolidColorBrush)ink).Color;var fill=new LinearGradientBrush(Color.FromArgb(7,color.R,color.G,color.B),Color.FromArgb(96,color.R,color.G,color.B),new Point(0,0),new Point(0,1));double fillHeight=(h-8)*Ratio;if(fillHeight>0)dc.DrawRoundedRectangle(fill,null,new Rect(4,h-4-fillHeight,Math.Max(1,w-8),fillHeight),14,14);}return;}double width=vertical?Math.Min(w,9*thickness):w,height=vertical?h:Math.Min(h,3*thickness);double x=(w-width)/2,y=(h-height)/2;dc.DrawRoundedRectangle(track,null,new Rect(x,y,width,height),Math.Min(4,width/2),Math.Min(4,height/2));if(!Available)return;var accent=((SolidColorBrush)ink).Color;var gradient=new LinearGradientBrush(Color.FromArgb(130,accent.R,accent.G,accent.B),accent,new Point(0,vertical?1:0),new Point(vertical?0:1,0));dc.DrawRoundedRectangle(gradient,null,vertical?new Rect(x,y+height*(1-Ratio),width,height*Ratio):new Rect(x,y,width*Ratio,height),Math.Min(4,width/2),Math.Min(4,height/2));}
 }
